create table purchases (id uuid primary key default gen_random_uuid(),purchase_date date not null,item_type purchase_item_type not null,item_code text not null,supplier_id uuid references suppliers(supplier_id),qty_purchased numeric(16,3) not null check(qty_purchased>0),rate numeric(16,4) not null check(rate>=0),amount numeric(16,4) generated always as(qty_purchased*rate) stored,invoice_no text not null unique);
create table stock_transfers (id uuid primary key default gen_random_uuid(),transfer_date date not null,item_code text not null,qty numeric(16,3) not null check(qty>0),adjustment_type stock_adjustment_type not null,destination_department text,performed_by uuid references users(user_id),notes text);
create table stock_audits (id uuid primary key default gen_random_uuid(),audit_date date not null,item_code text not null,system_stock_qty numeric(16,3) not null,physical_counted_qty numeric(16,3) not null,variance numeric(16,3) generated always as(physical_counted_qty-system_stock_qty) stored,action text not null check(action in('Accept & Adjust','Investigate / Hold')),performed_by uuid references users(user_id),notes text);

